-- Forever dungeon facts from the game itself, so no other addon is needed:
-- the group finder lists every dungeon with its suggested level range and
-- group size in the client's language, and Wisp's generated entrance table
-- (Data/DungeonEntrances.lua, generated by @wisp/game-data from the game's
-- Map tables) places each entrance. Data/GroupFinderNames.lua gives each
-- activity's English name, so English names match on a localized client.
local _, ns = ...
local sharedText = ns.Shared.Text

local DUNGEON_CATEGORY = 2

local function text(value)
    return type(value) == "string" and sharedText.TruncateUtf8Bytes(value, 160) or nil
end

local function level(value)
    return type(value) == "number" and value > 0 and value or nil
end

-- The group finder's dungeon activities, or nil when the game cannot list them.
local function activities()
    local lfg = C_LFGList
    if not (lfg and lfg.GetAvailableActivities and lfg.GetActivityInfoTable) then
        return nil
    end
    local ok, ids = pcall(lfg.GetAvailableActivities)
    if not ok or type(ids) ~= "table" then
        return nil
    end
    local out = {}
    for _, id in ipairs(ids) do
        local read, info = pcall(lfg.GetActivityInfoTable, id)
        if read and type(info) == "table" and info.categoryID == DUNGEON_CATEGORY then
            out[#out + 1] = { id = id, info = info }
        end
    end
    return out
end

-- Lua's string.lower leaves non-ASCII letters alone, so names are folded for
-- matching: lowercased, then Latin-1 letters (UTF-8 C3 80-BF) lose their
-- accents, so "sima ígnea", "Sima Ígnea" and "sima ignea" all match.
local FOLD = {}
for base, bytes in pairs({
    a = { 128, 129, 130, 131, 132, 133, 160, 161, 162, 163, 164, 165 },
    c = { 135, 167 },
    e = { 136, 137, 138, 139, 168, 169, 170, 171 },
    i = { 140, 141, 142, 143, 172, 173, 174, 175 },
    n = { 145, 177 },
    o = { 146, 147, 148, 149, 150, 178, 179, 180, 181, 182 },
    u = { 153, 154, 155, 156, 185, 186, 187, 188 },
    y = { 157, 189, 191 },
}) do
    for _, byte in ipairs(bytes) do
        FOLD[string.char(195, byte)] = base
    end
end

local function fold(value)
    return (value:lower():gsub("\195[\128-\191]", FOLD))
end

local function zoneName(mapId)
    local info = C_Map and C_Map.GetMapInfo and C_Map.GetMapInfo(mapId)
    return info and text(info.name) or nil
end

local function entrances(instanceMapId)
    local known = ns.Data.DungeonEntrances[instanceMapId]
    if not known then
        return nil
    end
    local out = {}
    for _, point in ipairs(known.entrances) do
        out[#out + 1] = { mapId = point[1], zone = zoneName(point[1]), x = point[2], y = point[3] }
    end
    return out
end

-- The instance's name in the client's language when the game has it.
local function instanceName(instanceMapId, fallback)
    local name = GetRealZoneText and GetRealZoneText(instanceMapId)
    return text(name ~= "" and name or fallback)
end

-- Every group finder activity (a wing is its own activity), then the table's
-- raids and dungeons the group finder does not list. instanceName is the
-- instance's English name, shared by its wings, so "Scarlet Monastery" finds
-- every wing; englishName is the activity's own.
local function list(activityList)
    local out, listed = {}, {}
    for _, activity in ipairs(activityList or {}) do
        local info = activity.info
        local known = ns.Data.DungeonEntrances[info.mapID]
        listed[info.mapID] = true
        out[#out + 1] = {
            name = text(info.fullName),
            englishName = ns.Data.GroupFinderNames[activity.id],
            instanceName = known and known.name or nil,
            instanceMapId = info.mapID,
            minLevel = level(info.minLevelSuggestion),
            maxLevel = level(info.maxLevelSuggestion),
            players = info.maxNumPlayers,
            entrances = entrances(info.mapID),
        }
    end
    for id, known in pairs(ns.Data.DungeonEntrances) do
        if not listed[id] then
            out[#out + 1] = {
                name = instanceName(id, known.name),
                englishName = known.name,
                instanceMapId = id,
                raid = known.raid or nil,
                players = known.players,
                entrances = entrances(id),
                notInGroupFinder = true,
            }
        end
    end
    table.sort(out, function(a, b)
        local la, lb = a.minLevel or 99, b.minLevel or 99
        if la ~= lb then
            return la < lb
        end
        return (a.name or "") < (b.name or "")
    end)
    return out
end

local function matches(entry, wanted)
    for _, name in ipairs({ entry.name, entry.englishName, entry.instanceName }) do
        if type(name) == "string" and fold(name):find(wanted, 1, true) then
            return true
        end
    end
    return false
end

function ns.Character.ReadDungeons(args)
    local activityList = activities()
    local dungeons = list(activityList)
    assert(dungeons[1], "Neither the group finder nor Wisp's entrance table lists any dungeon")
    local result = {
        characterLevel = UnitLevel and UnitLevel("player") or nil,
        faction = UnitFactionGroup and UnitFactionGroup("player") or nil,
        -- false: the game's group finder could not be read, so no entry has a
        -- level range and the list holds only the entrance table's instances.
        groupFinder = activityList ~= nil,
    }
    if not args.dungeon then
        result.dungeons = dungeons
        return result
    end
    local wanted, found = fold(args.dungeon), {}
    for _, entry in ipairs(dungeons) do
        if matches(entry, wanted) then
            found[#found + 1] = entry
        end
    end
    assert(
        found[1],
        "No dungeon named "
            .. args.dungeon
            .. "; read the list without a name for the names the game uses"
    )
    result.dungeons = found
    return result
end
